// Shared lock with GitHub Actions. Stop the 8:50/5:50 fallback when this date+slot is claimed or posted
// in _data/slot-claims.json, OR when _data/history.json already has a post for this date+slot.
const cfg = $('Config').first().json;
function readDoc(resp, label, empty) {
  resp = resp || {};
  const msg = String(resp.message || '');
  if (resp.content) {
    try { return JSON.parse(Buffer.from(resp.content, 'base64').toString('utf8')); }
    catch (e) { throw new Error(label + ' was not valid JSON - fallback stopped to avoid a double post'); }
  }
  if (/not found/i.test(msg)) return empty;
  if (!msg && !resp.sha && !resp.size) return empty;
  throw new Error('Could not read ' + label + ' (' + (msg || 'no content, size ' + resp.size).slice(0, 180) + ') - fallback stopped to avoid a double post');
}
const doc = readDoc($('GH Get Slot Claims').first().json, '_data/slot-claims.json', { claims: {} });
const hist = readDoc($input.first().json, '_data/history.json', { posted: [] });
const key = cfg.today + ':' + cfg.slot;
const row = (doc.claims || {})[key] || null;
const status = row && String(row.status || '').toLowerCase();
const posted = (hist.posted || []).find(p => p && p.date === cfg.today && Number(p.slot) === Number(cfg.slot)) || null;
const wouldBlock = status === 'claimed' || status === 'posted' || !!posted;
